import os
import json
import base64
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding
from cryptography.hazmat.backends import default_backend
import hashlib
import time

# Session token encryption service for user authentication tokens
# Deployed as a containerized microservice

SECRET_KEY = os.environ.get('ENCRYPTION_KEY', 'default-key-for-dev-only-1234567')
BLOCK_SIZE = 128

def get_cipher_key():
    return hashlib.sha256(SECRET_KEY.encode()).digest()

def decrypt_session_token(encrypted_token_b64):
    """Decrypt a session token and return the plaintext payload.
    Uses AES-CBC with PKCS7 padding."""
    try:
        raw = base64.b64decode(encrypted_token_b64)
        if len(raw) < 32:  # IV (16) + at least one block (16)
            return None, "invalid_token_length"

        iv = raw[:16]
        ciphertext = raw[16:]

        key = get_cipher_key()
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
        decryptor = cipher.decryptor()

        padded_plaintext = decryptor.update(ciphertext) + decryptor.finalize()

        # Validate PKCS7 padding
        unpadder = padding.PKCS7(BLOCK_SIZE).unpadder()
        try:
            plaintext = unpadder.update(padded_plaintext) + unpadder.finalize()
            return plaintext.decode('utf-8'), None
        except ValueError:
            # Padding validation failed
            return None, "invalid_padding"

    except Exception as e:
        return None, "decryption_error"

def validate_token_structure(plaintext):
    """Validate the decrypted token has expected JSON structure."""
    try:
        data = json.loads(plaintext)
        required = ['user_id', 'exp', 'role']
        if not all(k in data for k in required):
            return None, "missing_fields"
        if data['exp'] < time.time():
            return None, "token_expired"
        return data, None
    except json.JSONDecodeError:
        return None, "invalid_json"

def handler(event, context=None):
    """Main request handler for token validation endpoint.
    Accepts POST with encrypted session token, returns validation result."""

    try:
        if isinstance(event, str):
            body = json.loads(event)
        elif 'body' in event:
            body = json.loads(event['body']) if isinstance(event['body'], str) else event['body']
        else:
            body = event
    except (json.JSONDecodeError, TypeError):
        return response(400, {"error": "invalid_request_body"})

    token = body.get('session_token')
    if not token:
        return response(400, {"error": "missing_session_token"})

    plaintext, error = decrypt_session_token(token)

    if error == "invalid_padding":
        # Return specific error for padding failures to aid client debugging
        return response(403, {"error": "token_integrity_check_failed", "code": "PADDING_ERROR"})
    elif error == "invalid_token_length":
        return response(400, {"error": "malformed_token", "code": "LENGTH_ERROR"})
    elif error:
        return response(500, {"error": "internal_decryption_failure", "code": "DECRYPT_ERROR"})

    token_data, validation_error = validate_token_structure(plaintext)
    if validation_error:
        return response(403, {"error": "invalid_token_content", "code": validation_error.upper()})

    return response(200, {
        "valid": True,
        "user_id": token_data['user_id'],
        "role": token_data['role']
    })

def response(status_code, body):
    return {
        "statusCode": status_code,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(body)
    }

# Container entrypoint for ECS Fargate
if __name__ == "__main__":
    from flask import Flask, request
    app = Flask(__name__)

    @app.route('/validate', methods=['POST'])
    def validate():
        event = {'body': request.get_data(as_text=True)}
        result = handler(event)
        return app.response_class(
            response=result['body'],
            status=result['statusCode'],
            mimetype='application/json'
        )

    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
